        mode==="PATROL"?pick("Crawl","Walking"):
        mode==="INVESTIGATE"||mode==="SEARCH"?pick("Alert","Idle","Walking"):
        mode==="RETREAT"?pick("Walking","Crawl"):
        pick("Idle","Walking");
